from auto_config.generator.gnb.managed_objects.managed_object import ManagedObject


class ToppParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        if self.is_mo_ecpri:
            self.set_parameter('topEthMulticastAddress', "01-80-C2-00-00-0E")
            self.set_parameter('topStandardProfile', "G.8275.1")
            self.set_struct_parameter('topMasterList', "topMasterId", "1")
            self.set_parameter('acceptedClockClass', (7, 6))  # struct parameter w/o #p attribute (see xmltodict doc)
        if execution_config['release'] <= 25.32508:
            self.set_parameter('ptpMonDomainNumber', '44')
